PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "remember_token" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" varchar not null, "queue" varchar not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "categories" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "units" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "medicines" ("id" integer primary key autoincrement not null, "name" varchar not null, "type" varchar not null, "description" varchar, "dosage" varchar, "unit_id" integer, "category_id" integer, "unit_price" numeric, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("unit_id") references "units"("id") on delete set null, foreign key("category_id") references "categories"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "patients" ("id" integer primary key autoincrement not null, "khmer_first_name" varchar not null, "khmer_last_name" varchar not null, "first_name" varchar, "last_name" varchar, "date_of_birth" varchar not null, "address" integer, "blood_group" varchar, "phone_number" varchar not null, "gender" varchar not null, "allergy" varchar, "register_by" integer, "last_modifier" integer, "national_id" varchar, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("register_by") references "users"("id") on delete set null, foreign key("last_modifier") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "paraclinic_request_tests" ("id" integer primary key autoincrement not null, "paraclinic_request_id" integer not null, "test_category" varchar not null, "test_name" varchar not null, "priority" varchar not null default 'Routine', "instruction" text, "created_at" datetime, "updated_at" datetime, foreign key("paraclinic_request_id") references "paraclinic_requests"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "paraclinic_results" ("id" integer primary key autoincrement not null, "paraclinic_request_id" integer not null, "result_date" date, "result_summary" text, "doctor_interpretation" text, "reviewed_by" integer, "reviewed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("paraclinic_request_id") references "paraclinic_requests"("id") on delete cascade, foreign key("reviewed_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "paraclinic_attachments" ("id" integer primary key autoincrement not null, "paraclinic_request_id" integer not null, "file_name" varchar not null, "file_path" varchar not null, "mime_type" varchar not null, "file_size" integer not null, "uploaded_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("paraclinic_request_id") references "paraclinic_requests"("id") on delete cascade, foreign key("uploaded_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "visits" ("id" integer primary key autoincrement not null, "patient_id" integer not null, "type" varchar not null default 'OPD', "status" varchar not null default 'active', "visit_date" datetime not null default CURRENT_TIMESTAMP, "recorded_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("patient_id") references "patients"("id") on delete cascade, foreign key("recorded_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "consultations" ("id" integer primary key autoincrement not null, "patient_id" integer not null, "weight" numeric, "chief_complaint" varchar not null, "respiratory_system_symptoms" text, "respiratory_system_others_note" varchar, "cardiovascular_symptoms" text, "cardiovascular_others_note" varchar, "neurological_symptoms" text, "neurological_others_note" varchar, "musculoskeletal_symptoms" text, "musculoskeletal_others_note" varchar, "digestive_symptoms" text, "digestive_others_note" varchar, "renal_reproductive_symptoms" text, "renal_reproductive_others_note" varchar, "skin_symptoms" text, "skin_others_note" varchar, "eye_symptoms" text, "eye_others_note" varchar, "ear_symptoms" text, "ear_others_note" varchar, "nose_symptoms" text, "nose_others_note" varchar, "throat_symptoms" text, "throat_others_note" varchar, "psycology_symptoms" text, "psycology_others_note" varchar, "diagnosis" varchar, "note" text, "fee" numeric, "recorded_by" integer, "created_at" datetime, "updated_at" datetime, "visit_id" integer, foreign key("recorded_by") references users("id") on delete set null on update no action, foreign key("patient_id") references patients("id") on delete cascade on update no action, foreign key("visit_id") references "visits"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "paraclinic_requests" ("id" integer primary key autoincrement not null, "request_number" varchar not null, "patient_id" integer not null, "doctor_id" integer not null, "external_facility_name" varchar, "request_date" date not null, "clinical_reason" text, "provisional_diagnosis" varchar, "notes" text, "status" varchar not null default ('Draft'), "subtotal" numeric not null default ('0'), "discount" numeric not null default ('0'), "total_amount" numeric not null default ('0'), "payment_status" varchar not null default ('Unpaid'), "payment_date" date, "created_by" integer, "updated_by" integer, "deleted_at" datetime, "created_at" datetime, "updated_at" datetime, "visit_id" integer, foreign key("patient_id") references patients("id") on delete cascade on update no action, foreign key("doctor_id") references users("id") on delete cascade on update no action, foreign key("created_by") references users("id") on delete set null on update no action, foreign key("updated_by") references users("id") on delete set null on update no action, foreign key("visit_id") references "visits"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "patient_surveillances" ("id" integer primary key autoincrement not null, "patient_id" integer not null, "systolic" integer not null, "diastolic" integer not null, "pulse" integer not null, "temperature" numeric not null, "rr" integer not null, "spo2" integer not null, "o2_supply" varchar not null, "recorded_by" integer, "created_at" datetime, "updated_at" datetime, "visit_id" integer, foreign key("recorded_by") references users("id") on delete set null on update no action, foreign key("patient_id") references patients("id") on delete cascade on update no action, foreign key("visit_id") references "visits"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "patient_attachments" ("id" integer primary key autoincrement not null, "patient_id" integer not null, "file_name" varchar not null, "file_path" varchar not null, "file_type" varchar not null, "file_size" integer not null, "uploaded_by" integer, "created_at" datetime, "updated_at" datetime, "visit_id" integer, foreign key("uploaded_by") references users("id") on delete set null on update no action, foreign key("patient_id") references patients("id") on delete cascade on update no action, foreign key("visit_id") references "visits"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "medication_administrations" ("id" integer primary key autoincrement not null, "visit_id" integer not null, "medicine_id" integer, "route" varchar not null, "dosage" numeric not null, "unit" varchar not null, "interval" varchar not null, "status" varchar not null default 'prescribed', "notes" text, "created_by" integer, "created_at" datetime, "updated_at" datetime, "starts_at" datetime, "stopped_at" datetime, "cycle_no" integer not null default '1', "duration" integer, foreign key("visit_id") references "visits"("id") on delete cascade, foreign key("medicine_id") references "medicines"("id") on delete set null, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "vaccines" ("id" integer primary key autoincrement not null, "name" varchar not null, "description" text, "rules" text not null, "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "patient_vaccinations" ("id" integer primary key autoincrement not null, "patient_id" integer not null, "vaccine_id" integer not null, "dose_number" integer not null, "administered_date" date not null, "notes" text, "administered_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("patient_id") references "patients"("id") on delete cascade, foreign key("vaccine_id") references "vaccines"("id") on delete cascade, foreign key("administered_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "appointments" ("id" integer primary key autoincrement not null, "patient_id" integer not null, "appointment_date" date not null, "appointment_time" time, "type" varchar not null default 'consultation', "status" varchar not null default 'scheduled', "notes" text, "vaccine_alerts" text, "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("patient_id") references "patients"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "medication_doses" ("id" integer primary key autoincrement not null, "medication_administration_id" integer not null, "scheduled_at" datetime not null, "administered_at" datetime, "status" varchar not null default 'pending', "administered_by" integer, "unit_price" numeric, "reason" text, "created_at" datetime, "updated_at" datetime, "cycle_no" integer not null default '1', "administration_no" integer, "total_administrations" integer, "note" text, foreign key("medication_administration_id") references "medication_administrations"("id") on delete cascade, foreign key("administered_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "prescriptions" ("id" integer primary key autoincrement not null, "visit_id" integer not null, "notes" text, "created_by" integer, "created_at" datetime, "updated_at" datetime, foreign key("visit_id") references "visits"("id") on delete cascade, foreign key("created_by") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "prescription_items" ("id" integer primary key autoincrement not null, "prescription_id" integer not null, "medicine_id" integer not null, "route" varchar not null, "dosage" numeric not null, "unit" varchar not null, "frequency" varchar not null, "duration_days" integer, "quantity" numeric, "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("prescription_id") references "prescriptions"("id") on delete cascade, foreign key("medicine_id") references "medicines"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "medication_audits" ("id" integer primary key autoincrement not null, "user_id" integer, "action" varchar not null, "auditable_type" varchar not null, "auditable_id" integer not null, "old_values" text, "new_values" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete set null);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "cache_expiration_index" on "cache" ("expiration");
CREATE INDEX "cache_locks_expiration_index" on "cache_locks" ("expiration");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE INDEX "failed_jobs_connection_queue_failed_at_index" on "failed_jobs" ("connection", "queue", "failed_at");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "categories_name_unique" on "categories" ("name");
CREATE UNIQUE INDEX "units_name_unique" on "units" ("name");
CREATE UNIQUE INDEX "medicines_name_unique" on "medicines" ("name");
CREATE UNIQUE INDEX "patients_phone_number_national_id_unique" on "patients" ("phone_number", "national_id");
CREATE UNIQUE INDEX "paraclinic_requests_request_number_unique" on "paraclinic_requests" ("request_number");
CREATE INDEX "patient_vaccinations_patient_id_vaccine_id_index" on "patient_vaccinations" ("patient_id", "vaccine_id");
CREATE INDEX "medication_doses_medication_administration_id_scheduled_at_index" on "medication_doses" ("medication_administration_id", "scheduled_at");
CREATE INDEX "medication_doses_status_scheduled_at_index" on "medication_doses" ("status", "scheduled_at");
CREATE INDEX "medication_audits_auditable_type_auditable_id_index" on "medication_audits" ("auditable_type", "auditable_id");
COMMIT;
